521	  void _onFsFrame(List<int> data) {
522	    final CompanionFsFrame frame;
523	    try {
524	      frame = CompanionFsFrame.fromBytes(data);
525	    } catch (e) {
526	      AppLog.w(_tag, 'FS 帧解析失败: $e');
527	      return;
528	    }
529	
530	    if (frame.cmd == CompanionFs.need) {
531	      if (!frame.isErr && frame.status == 0) {
532	        final name = utf8.decode(frame.payload, allowMalformed: true);
533	        _enqueueIconNeed(name);
534	      }
535	      return;
536	    }
537	
538	    if (frame.cmd == CompanionFs.writeData &&
539	        (frame.isErr || frame.status != 0)) {
540	      _fsWritePushErr ??= CompanionFsException(
541	        '设备返回 errno=${frame.status}',
542	        status: frame.status,
543	      );
544	      return;
545	    }
546	
547	    final wait = _fsWait;
548	    if (wait == null || wait.isCompleted) return;
549	    if (frame.tid != _fsWaitTid || frame.cmd != _fsWaitCmd) return;
550	
551	    if (frame.isErr || frame.status != 0) {
552	      wait.completeError(
553	        CompanionFsException(
554	          '设备返回 errno=${frame.status}',
555	          status: frame.status,
556	          partial: _concatFsPayloads(),
557	        ),
558	      );
559	      _fsWait = null;
560	      return;
561	    }
562	
563	    if (frame.seq != _fsCollected.length) {
564	      /* 固件在 LIST 之后可能没把 seq 清零，单帧 STAT/READ 会带着 seq=1 LAST。
565	       * 这仍是完整回复，不能当成缺包。多帧中间缺号才失败。
566	       */
567	      if (frame.isLast && _fsCollected.isEmpty && frame.seq <= 1) {
568	        AppLog.w(
569	          _tag,
570	          'FS seq=${frame.seq} 但仅 LAST 一帧，按完整回复接收 '
571	          'cmd=0x${frame.cmd.toRadixString(16)} tid=${frame.tid}',
572	        );
573	        _fsCollected.add(frame);
574	        wait.complete(List<CompanionFsFrame>.from(_fsCollected));
575	        _fsWait = null;
576	        return;
577	      }
578	      AppLog.w(
579	        _tag,
580	        'FS seq 不连续: cmd=0x${frame.cmd.toRadixString(16)} '
581	        'tid=${frame.tid} 期望 ${_fsCollected.length} 收到 ${frame.seq}'
582	        '${frame.isLast ? " LAST" : ""}',
583	      );
584	      wait.completeError(
585	        CompanionFsException(
586	          'FS seq 不连续: 期望 ${_fsCollected.length} 收到 ${frame.seq}',
587	          partial: _concatFsPayloads(),
588	        ),
589	      );
590	      _fsWait = null;
591	      return;
592	    }
593	
594	    _fsCollected.add(frame);
595	    if (frame.isLast) {
596	      wait.complete(List<CompanionFsFrame>.from(_fsCollected));
597	      _fsWait = null;
598	    }
599	  }
