601	  Uint8List _concatFsPayloads() {
602	    final n = _fsCollected.fold<int>(0, (s, f) => s + f.payload.length);
603	    final out = Uint8List(n);
604	    var o = 0;
605	    for (final f in _fsCollected) {
606	      out.setAll(o, f.payload);
607	      o += f.payload.length;
608	    }
609	    return out;
610	  }
