618	  Future<Uint8List> _fsCommand(
619	    int cmd,
620	    List<int> payload, {
621	    Duration timeout = const Duration(seconds: 20),
622	  }) async {
623	    final cmdChar = _fsCmdChar;
624	    if (cmdChar == null || _fsDataChar == null) {
625	      throw StateError('Companion FS 特征不可用');
626	    }
627	    if (_fsWait != null) {
628	      throw StateError('已有 FS 事务进行中');
629	    }
630	
631	    final tid = _nextFsTid();
632	    _fsCollected.clear();
633	    _fsWaitTid = tid;
634	    _fsWaitCmd = cmd;
635	    final wait = Completer<List<CompanionFsFrame>>();
636	    _fsWait = wait;
637	
638	    final pkt = Uint8List(2 + payload.length);
639	    pkt[0] = cmd;
640	    pkt[1] = tid;
641	    pkt.setAll(2, payload);
642	
643	    try {
644	      await cmdChar.write(
645	        pkt,
646	        withoutResponse: cmdChar.properties.writeWithoutResponse,
647	      );
648	      await wait.future.timeout(timeout);
649	    } on TimeoutException {
650	      if (!wait.isCompleted) {
651	        wait.completeError(
652	          CompanionFsException('FS 等待超时', partial: _concatFsPayloads()),
653	        );
654	      }
655	      _fsWait = null;
656	      await AppLog.w(
657	        _tag,
658	        'FS 等待超时 cmd=0x${cmd.toRadixString(16)} tid=$tid '
659	        '已收 ${_fsCollected.length} 帧',
660	      );
661	      throw CompanionFsException(
662	        'FS 等待超时',
663	        partial: _concatFsPayloads(),
664	      );
665	    } catch (e) {
666	      _fsWait = null;
667	      rethrow;
668	    }
669	
670	    final body = _concatFsPayloads();
671	    if (cmd == CompanionFs.read) {
672	      AppLog.i(
673	        _tag,
674	        'READ tid=$tid ${_fsCollected.length} 帧 ${body.length} B',
675	      );
676	    }
677	    return body;
678	  }
