```dart
  /// 串行执行一次 FS 事务。
  ///
  /// `0xFF15`/`0xFF16` 是单通道：一次只能有一个事务在等回复，否则
  /// [_fsWaitTid]/[_fsWaitCmd]/[_fsCollected] 会被后一个覆盖，两个调用方双双超时。
  /// 设备主动索要图标是随机时机的，所以并发是常态而非例外 —— 以前只有 icon 路径
  /// 忙等规避，其余调用方直接抛错。这里改成 FIFO 排队：
  ///
  /// - 下载/上传这类多步事务整体持锁，中间不会被别的命令插进来；
  /// - 后来者排队等待，而不是立刻失败。
  Future<T> _withFsLock<T>(Future<T> Function() body) async {
    final prev = _fsLock;
    final gate = Completer<void>();
    _fsLock = gate.future;
    try {
      await prev;
      return await body();
    } finally {
      // gate 只用 complete，不带错误，队列不会因为一次失败卡死。
      gate.complete();
    }
  }
```

