165	  int? _hitIndex(LatLng display) {
166	    try {
167	      final cam = _map.camera;
168	      final tap = cam.latLngToScreenOffset(display);
169	      var best = -1;
170	      var bestD = 36.0;
171	      for (var i = 0; i < _points.length; i++) {
172	        final p = cam.latLngToScreenOffset(HelmOsmTiles.toDisplay(_points[i]));
173	        final d = (p - tap).distance;
174	        if (d < bestD) {
175	          bestD = d;
176	          best = i;
177	        }
178	      }
179	      return best >= 0 ? best : null;
180	    } catch (_) {
181	      return null;
182	    }
183	  }
