212	  Future<void> _addAt(LatLng wgs) async {
213	    if (_isNav && _stops.length >= _maxNav) {
214	      AppTheme.snack(
215	        LocaleKeys.navRoutesTitle.tr,
216	        LocaleKeys.navRouteMaxPts.tr,
217	      );
218	      return;
219	    }
220	    setState(() => _busy = true);
221	    try {
222	      final snapped = await RoadRouter.instance.snap(wgs);
223	      if (!mounted) return;
224	      final insertAt = _insertIndex();
225	      final label = LocaleKeys.navRouteStopDefault.trParams({
226	        'n': '${_stops.length + 1}',
227	      });
228	      final stop = NavStop(name: label, point: snapped);
229	      final appended = insertAt >= _stops.length;
230	      _stops.insert(insertAt, stop);
231	      _selected = insertAt;
232	      _moving = false;
233	      _touch();
234	      if (appended && !_isNav && _stops.length >= 2) {
235	        final from = _stops[_stops.length - 2].point;
236	        final leg = await RoadRouter.instance.route(from, snapped);
237	        if (leg.length >= 2) {
238	          _stops.last.point = leg.last;
239	          if (_routed.length < 2) {
240	            _routed = List<LatLng>.from(leg);
241	          } else {
242	            _routed = [..._routed, ...leg.skip(1)];
243	          }
244	        } else {
245	          throw const RoadRouterException('no route');
246	        }
247	      } else {
248	        await _rebuildRouted(keepBusy: true);
249	      }
250	      if (mounted) setState(() {});
251	    } on RoadRouterException {
252	      if (!mounted) return;
253	      AppTheme.snack(
254	        _isNav
255	            ? LocaleKeys.navRouteEditorTitle.tr
256	            : LocaleKeys.gpxEditorTitle.tr,
257	        LocaleKeys.roadSnapFail.tr,
258	      );
259	    } catch (e, st) {
260	      if (!mounted) return;
261	      AppTheme.failText('Waypoint', e, st);
262	      AppTheme.snack(
263	        _isNav
264	            ? LocaleKeys.navRouteEditorTitle.tr
265	            : LocaleKeys.gpxEditorTitle.tr,
266	        LocaleKeys.roadRouteFail.tr,
267	      );
268	    } finally {
269	      if (mounted) setState(() => _busy = false);
270	    }
271	  }
