Future<void> animateCamera(
  MapController map,
  LatLng target, {
  double? zoom,
  required TickerProvider vsync,
  Duration duration = const Duration(milliseconds: 320),
}) async {
  final cam = map.camera;
  final from = cam.center;
  final fromZoom = cam.zoom;
  final toZoom = zoom ?? fromZoom;
  // 经纬度跨日界线时不处理，编辑场景不涉及。
  final ctrl = AnimationController(vsync: vsync, duration: duration);
  final t = CurvedAnimation(parent: ctrl, curve: Curves.easeOutCubic);
  void tick() {
    final v = t.value;
    map.move(
      LatLng(
        from.latitude + (target.latitude - from.latitude) * v,
        from.longitude + (target.longitude - from.longitude) * v,
      ),
      fromZoom + (toZoom - fromZoom) * v,
    );
  }
  ctrl.addListener(tick);
  try {
    await ctrl.forward();
  } finally {
    ctrl.dispose();  // 立刻释放，调用方不需要管
