  /// 按当前锚点重建沿路折线（gpx 模式）。
  ///
  /// 各段并行 + 结果缓存，通常只等最慢的一段；代号对不上就丢弃，连点不会互相覆盖。
  Future<void> _rebuildRouted() async {
    if (_isNav || _stops.length < 2) {
      _routed = List<LatLng>.from(_points);
      if (mounted) setState(() {});
      return;
    }

    final gen = ++_routeGen;
    _beginWork(LocaleKeys.mapEditorRouting.tr);
    try {
      final pts = await RoadRouter.instance.routeAnchors(_points);
      if (!mounted || gen != _routeGen) return;
      setState(() {
        _routed = pts;
        if (_routed.length >= 2) {
          _stops.first.point = _routed.first;
          _stops.last.point = _routed.last;
        }
      });
    } catch (e, st) {
      if (!mounted || gen != _routeGen) return;
      AppTheme.failText('Waypoint', e, st);
      AppTheme.snack(LocaleKeys.gpxEditorTitle.tr, LocaleKeys.roadRouteFail.tr);
    } finally {
      _endWork();
    }
  }
```
Careful: `_routeGen` isn't incremented in the early-return branch — that's fine (no request in flight for that branch). But: if a request IS in flight and the user then deletes down to 1 stop, the early-return branch runs and sets `_routed = _points`; the in-flight request will later come back with `gen == _routeGen` still (since we didn't bump) → it would overwrite `_routed` with stale data! Fix: bump `_routeGen` in the early-return branch too, invalidating in-flight work. Let me do that: `_routeGen++;` at the top of the early-return branch.

