class _PacePainter extends CustomPainter {
  _PacePainter({required this.speeds});

  final List<double> speeds;

  static const _slow = Color(0xFF3DDC84);
  static const _mid = Color(0xFFFFD54A);
  static const _fast = Color(0xFFFF5C33);

  @override
  void paint(Canvas canvas, Size size) {
    final r = RRect.fromRectAndRadius(
      Offset.zero & size,
      const Radius.circular(5),
    );
    canvas.save();
    canvas.clipRRect(r);
    if (speeds.length < 2) {
      canvas.drawRRect(
        r,
        Paint()
          ..shader = const LinearGradient(
            colors: [_slow, _mid, _fast],
          ).createShader(Offset.zero & size),
      );
    } else {
      var minV = speeds.reduce(math.min);
      var maxV = speeds.reduce(math.max);
      if (maxV - minV < 0.4) {
        minV -= 0.5;
        maxV += 0.5;
      }
      final span = maxV - minV;
      final w = size.width / speeds.length;
      for (var i = 0; i < speeds.length; i++) {
        final t = ((speeds[i] - minV) / span).clamp(0.0, 1.0);
        final c = t < 0.5
            ? Color.lerp(_slow, _mid, t * 2)!
            : Color.lerp(_mid, _fast, (t - 0.5) * 2)!;
        canvas.drawRect(Rect.fromLTWH(i * w, 0, w + 0.6, size.height), Paint()..color = c);
      }
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _PacePainter old) => old.speeds != speeds;
}


