static List<double> cumulativeRideSeconds(List<LatLng> pts, List<double> speedsAtPoint, {double fallbackKmh = 18}) {
  final n = pts.length;
  final out = List<double>.filled(n, 0);
  var acc = 0.0;
  for (var i = 1; i < n; i++) {
    final dKm = _haversineKm(pts[i-1], pts[i]);
    var v = i < speedsAtPoint.length ? speedsAtPoint[i] : fallbackKmh;
    if (!(v > 0.2)) v = fallbackKmh;
    acc += dKm / v * 3600.0;   // km / (km/h) → h → s
    out[i] = acc;
  }
  return out;
}
```
