    if (v < 0) v = 0;
    if (v < 18) {
      final t = v / 18;
      return Color.fromARGB(
        255,
        (20 + 20 * t).round(),
        (168 + 42 * t).round(),
        (72 + 28 * t).round(),
      );
    }
    if (v < 32) {
      final t = (v - 18) / 14;
      return Color.fromARGB(
        255,
        (40 * (1 - t)).round(),
        (210 - 50 * t).round(),
        (100 + 120 * t).round(),
      );
    }
    final t = ((v - 32) / 16).clamp(0.0, 1.0);
    return Color.fromARGB(
      255,
      (255 * t).round(),
      (160 * (1 - t)).round(),
      (220 * (1 - t) + 32 * t).round(),
    );
  }

  /// 沿轨迹把速度做滑动平均，再抽成少量色标，画一条渐变线。
  static List<Polyline> speedPolylines(
    List<LatLng> disp,
    List<double> speedsAtPoint, {
    double? fallbackKmh,
  }) {
    if (disp.length < 2) return const [];
    final fb = fallbackKmh ?? 18;
    final colors = _avgGradient(disp.length, speedsAtPoint, fb);
    return [
      Polyline(
        points: disp,
        strokeWidth: 9,
        color: const Color(0xEEFFFFFF),
      ),
      Polyline(
        points: disp,
        strokeWidth: 5,
        color: colors[colors.length ~/ 2],
        gradientColors: colors,
      ),
    ];
  }

  static List<Color> _avgGradient(
    int n,
    List<double> speeds,
    double fallback,
  ) {
    final smooth = _smooth(n, speeds, fallback);
    const stops = 8;
    if (smooth.length == 1) {
      return [speedColor(smooth.first), speedColor(smooth.first)];
    }
    return [
      for (var i = 0; i < stops; i++)
        speedColor(
          smooth[((i / (stops - 1)) * (smooth.length - 1)).round()],
        ),
    ];
  }

  static List<double> _smooth(
    int n,
    List<double> speeds,
    double fallback,
  ) {
    final raw = List<double>.generate(n, (i) {
      if (i < speeds.length && speeds[i] > 0.2) return speeds[i];
      return fallback;
    });
    final win = (n / 10).round().clamp(6, 48);
