    if (_rideT.length != _disp.length || _rideTotal <= 0) {
      return _play.value * (_disp.length - 1);
    }
    final sec = _play.value * _rideTotal;
    var lo = 0;
    var hi = _rideT.length - 1;
    while (lo < hi) {
      final mid = (lo + hi) >> 1;
      if (_rideT[mid] < sec) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    final i = lo < 1 ? 1 : lo;
    final t0 = _rideT[i - 1];
    final t1 = _rideT[i];
    final f = t1 - t0 <= 0 ? 1.0 : ((sec - t0) / (t1 - t0)).clamp(0.0, 1.0);
    return (i - 1) + f;
