```dart
abstract class TrackName {
  /// 例：`9/17 08:30 玄武湖→南京南站`。地名缺失时退到坐标。
  static String of({
    DateTime? start,
    String? fromName,
    LatLng? from,
    String? toName,
    LatLng? to,
    int maxLabel = 8,
  }) {
    final when = start == null ? '' : _stamp(start.toLocal());
    final a = _clip(fromName ?? _coord(from), maxLabel);
    final b = _clip(toName ?? _coord(to), maxLabel);
    return [if (when.isNotEmpty) when, '$a→$b'].join(' ');
  }

  static String _stamp(DateTime l) =>
      '${l.month}/${l.day} ${l.hour.toString().padLeft(2, '0')}:${l.minute.toString().padLeft(2, '0')}';

  /// 地名太长会把列表撑爆，截断到 [maxLabel] 个字。
  static String _clip(String s, int maxLabel) {
    final t = s.trim();
    return t.length <= maxLabel ? t : t.substring(0, maxLabel);
  }

