  static String? _offlineCity(LatLng wgs) {
    for (final c in OsmCityCatalog.cities) {
      if (wgs.latitude >= c.south &&
          wgs.latitude <= c.north &&
          wgs.longitude >= c.west &&
          wgs.longitude <= c.east) {
