      'lat': wgs.latitude.toStringAsFixed(6),
      'lon': wgs.longitude.toStringAsFixed(6),
      'accept-language': 'zh-CN',
      'zoom': '16',
    });
    if (!_hostAllowed(uri)) {
      await AppLog.w('PlaceLookup', '拒绝请求不可用的主机: ${uri.host}');
      return null;
