    final raw = List<double>.generate(n, (i) {
      if (i < speeds.length && speeds[i] > 0.2) return speeds[i];
      return fallback;
    });
    final out = List<double>.filled(n, fallback);
    for (var i = 0; i < n; i++) {
      var s = 0.0;
      var c = 0;
      final a = i - win;
      final b = i + win;
      for (var j = a; j <= b; j++) {
        if (j < 0 || j >= n) continue;
        s += raw[j];
        c++;
      }
      out[i] = c == 0 ? fallback : s / c;
    }
