  _PacePainter({required this.speeds, this.range});

  final List<double> speeds;
  final ({double lo, double hi})? range;

  @override
  void paint(Canvas canvas, Size size) {
    final r = RRect.fromRectAndRadius(
      Offset.zero & size,
      const Radius.circular(5),
    );
    canvas.save();
    canvas.clipRRect(r);
    if (speeds.length < 2) {
      canvas.drawRRect(
