static List<double> downsample(List<double> src, int maxN) {
  if (src.length <= maxN) return src;
  final out = <double>[];
  for (var i = 0; i < maxN; i++) {
    final idx = (i * (src.length - 1) / (maxN - 1)).round();
    out.add(src[idx]);
  }
  return out;
}

