import 'package:sifli_companion/log/app_log.dart';

/// 连接面板的阶段。**面板显示什么、是否显示，全部由它决定**。
enum ConnPhase {
  /// 不显示。
  idle,

  /// 正在扫描，面板里列设备供选择。
  scanning,

  /// 正在连接 / 发现服务（含后台自动回连）。
  connecting,

  /// 刚连上，停一会儿报个成功再收回去。
  connected,

  /// 失败了。**不会自己消失**，等用户处理。
  failed,
}

/// 码表连接的全局状态：扫描、配对、连接、断开。
///
/// 存在的理由：原来连接流程是「进一个二级页面 → 在页面里点连接」，连接状态只有
/// 设备页在画。于是后台自动回连时全应用没有任何反馈 —— 页面没弹出来，也没地方显示
/// 「正在连」或「连不上」。这里把状态提到全局，由挂在路由之外的
/// `ConnectionOverlay` 渲染，任何页面、任何时候都看得到。
class ConnectionCenter {
  /// 单例入口。由 `main.dart` 里 `Get.put(..., permanent: true)` 注册。
  static ConnectionCenter get to => Get.find<ConnectionCenter>();

  /// 状态变化通知。用流而不是 Rx：订阅方是挂在路由外的 overlay，只关心「该重画了」。
  final _ctrl = StreamController<void>.broadcast();

  /// 状态变化流。
  Stream<void> get changes => _ctrl.stream;

  ConnPhase _phase = ConnPhase.idle;
  ConnPhase get phase => _phase;

  String _notice = '';
  /// 失败原因 / 提示文案（已本地化）。
  String get notice => _notice;

  /// 成功连上后的回调，由 `ShellController` 注册（它要记设备、拉起前台服务、
  /// 重新允许自动重连）。用回调而不是直接 import UI 控制器：方向反过来才不脏。
  void Function()? onLinked;

  /// 连接超时兜底：BT 栈偶尔不回事件，面板不能永远转圈。
  static const _connectTimeout = Duration(seconds: 30);

  /// 连上后「已连接」停留多久再收回去。
  static const _doneHold = Duration(milliseconds: 1800);

  final _devices = <String, ScanResult>{};
  StreamSubscription<List<ScanResult>>? _scanSub;
  Timer? _hold;
  Timer? _timeout;
  bool _busy = false;

  /// 扫到的码表，信号强的在前。
  List<ScanResult> get devices {
    final list = _devices.values.toList();
    list.sort((a, b) => b.rssi.compareTo(a.rssi));
    return list;
  }

  /// 面板该不该显示。
  bool get visible => _phase != ConnPhase.idle;

  /// 现在是否在转圈（扫描 / 连接）。
  bool get busy =>
      _phase == ConnPhase.scanning || _phase == ConnPhase.connecting;

  /// 上次连过的设备名（连接中/已连接时显示用）。
  String get deviceLabel {
    final d = CompanionClient.instance.device;
    if (d == null) return '';
    return nameOf(d);
  }

  /// 设备显示名：优先广播名，退回平台名。
  static String nameOf(BluetoothDevice d) {
    if (d.platformName.isNotEmpty) return d.platformName;
    if (d.advName.isNotEmpty) return d.advName;
    return LocaleKeys.bleScanUnknownDevice.tr;
  }

  void _emit() {
    if (!_ctrl.isClosed) _ctrl.add(null);
  }

  void _set(ConnPhase p, {String notice = ''}) {
    _phase = p;
    _notice = notice;
    _emit();
  }

  void _cancelTimers() {
    _hold?.cancel();
    _hold = null;
    _timeout?.cancel();
    _timeout = null;
  }

  /// 用户点「连接码表」：打开面板并开始扫描。
  Future<void> open() async {
    _cancelTimers();
    await _stopScan();
    _devices.clear();
    _set(ConnPhase.scanning);
    await _scan();
  }

  /// 关掉面板。连接中不允许关（否则又变成「连没连上看不出来」）。
  void dismiss() {
    if (_phase == ConnPhase.connecting) return;
    _stopScan();
    _set(ConnPhase.idle);
  }

  /// 用户在面板里点了某台设备。
  Future<void> connectTo(ScanResult result) async {
    if (_busy) return;
    _busy = true;
    _cancelTimers();
    await _stopScan();
    final name = nameOf(result.device);
    _set(ConnPhase.connecting, notice: name);
    _timeout = Timer(_connectTimeout, () {
      if (_phase == ConnPhase.connecting) {
        _set(ConnPhase.failed, notice: LocaleKeys.bleScanConnectFailed.tr);
      }
    });

    try {
      final client = CompanionClient.instance;
      await client.connect(result.device);
      _cancelTimers();
      if (client.state == CompanionConnState.ready) {
        await _afterLinked();
      } else if (client.state == CompanionConnState.versionMismatch) {
        _set(ConnPhase.failed, notice: LocaleKeys.deviceMismatch.tr);
      } else {
        _set(ConnPhase.failed, notice: LocaleKeys.bleScanConnectFailed.tr);
      }
    } catch (e, st) {
      _cancelTimers();
      await AppLog.e('ConnCenter', '连接失败: $e', st);
      _set(ConnPhase.failed, notice: LocaleKeys.bleScanConnectFailed.tr);
    } finally {
      _busy = false;
    }
  }

  /// 连上之后的收尾：记录设备、拉起前台服务，并让 shell 重新允许自动重连。
  Future<void> _afterLinked() async {
    _set(ConnPhase.connected, notice: deviceLabel);
    onLinked?.call();
    _hold = Timer(_doneHold, () {
      if (_phase == ConnPhase.connected) _set(ConnPhase.idle);
    });
  }

  /// 失败后重试上一次的设备。
  Future<void> retry() async {
    final d = CompanionClient.instance.device;
    if (d == null) {
      await open();
      return;
    }
    await connectTo(ScanResult(
      device: d,
      advertisementData: AdvertisementData(
        advName: d.advName,
        txPowerLevel: null,
        appearance: null,
        connectable: true,
        manufacturerData: const {},
        serviceData: const {},
        serviceUuids: const [],
      ),
      rssi: -100,
      timeStamp: DateTime.now(),
    ));
  }

  Future<void> disconnect() async {
    _cancelTimers();
    _set(ConnPhase.idle);
    await CompanionClient.instance.disconnect();
  }

  /// 后台自动回连开始时把面板叫出来 —— 这是原来「什么都不显示」的修法。
  ///
  /// 只在还没有可见面板时切到 [ConnPhase.connecting]；已经在扫描或已经失败时不动，
  /// 免得把用户正在看的列表或错误提示顶掉。
  void noteLinking() {
    if (_phase == ConnPhase.scanning ||
        _phase == ConnPhase.failed ||
        _phase == ConnPhase.connecting) {
      return;
    }
    _set(ConnPhase.connecting, notice: deviceLabel);
  }

  /// 自动回连失败：面板留着并说明情况，别让「怎么连不上了」变成谜。
  void noteLinkFailed(String notice) {
    if (_phase == ConnPhase.connected || _phase == ConnPhase.scanning) return;
    _cancelTimers();
    _set(ConnPhase.failed, notice: notice);
  }

  /// 自动回连成功：走一次成功提示再收回去（用户此时可能不在设备页）。
  void noteLinked() {
