    _scanSub = null;
    try {
      await BleManager().stopScan();
    } catch (_) {}
  }

  /// 释放资源。App 退出时调用。
  Future<void> dispose() async {
    _cancelTimers();
    await _stopScan();
    await _ctrl.close();
  }
