import 'package:flutter/material.dart';
import 'package:sifli_companion/app/app_theme.dart';
import 'package:sifli_companion/ble/connection_center.dart';
import 'package:sifli_companion/i18n/locale_keys.dart';

/// 连接码表的悬浮面板。
///
/// 常态不显示。只要发生连接动作就从底部滑出来 —— 用户点的、或后台自动回连的
/// 都算；连上后停一下自己收回去，失败则**留着不走**（连接失败最忌讳自己消失）。
///
/// 挂在 `GetMaterialApp.builder` 里，位置在所有路由**之外**，所以切页 / 返回
/// 都带不走它。「自动回连什么都没显示」正是靠这一层解决的。
///
/// 这一层没有 `Overlay`、也没有 `Material` 约束链，所以：不能用 `tooltip:`，
/// 宽度必须由 [Positioned] 钉死。
class ConnectionOverlay extends StatefulWidget {
  /// 创建连接面板。
  const ConnectionOverlay({super.key});

  @override
  State<ConnectionOverlay> createState() => _ConnectionOverlayState();
}

class _ConnectionOverlayState extends State<ConnectionOverlay>
    with SingleTickerProviderStateMixin {
  /// 0 = 完全滑出屏幕下方，1 = 停在底部导航之上。
  late final AnimationController _slide;

  bool _visible = false;

  /// 面板最大宽度；窄屏再收一点。
  static const _panelMax = 340.0;

  /// 底部导航条高度，面板要浮在它上面。
  static const _navBar = 60.0;

  StreamSubscription<void>? _sub;

  @override
  void initState() {
    super.initState();
    _slide = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 280),
    );
    final center = ConnectionCenter.to;
    _visible = center.visible;
    if (_visible) _slide.value = 1;
    _sub = center.changes.listen((_) => _sync());
  }

  @override
  void dispose() {
    _sub?.cancel();
    _slide.dispose();
    super.dispose();
  }

  void _sync() {
    if (!mounted) return;
    final has = ConnectionCenter.to.visible;
    if (has != _visible) {
      _visible = has;
      if (has) {
        _slide.forward();
      } else {
        _slide.reverse();
      }
    }
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final mq = MediaQuery.of(context);
    final bottom = mq.padding.bottom + _navBar + 12;
    final w = _panelMax.clamp(0.0, mq.size.width - 24);

    return Positioned(
      left: 12,
      right: 12,
      bottom: bottom,
      child: Center(
        child: SizedBox(
          width: w,
          child: AnimatedBuilder(
            animation: _slide,
            builder: (context, child) {
              final t = Curves.easeOutCubic.transform(_slide.value);
              return FractionalTranslation(
                translation: Offset(0, 1.0 - t),
                child: Opacity(
                  opacity: t,
                  child: IgnorePointer(ignoring: !_visible, child: child),
                ),
              );
            },
            child: _card(),
          ),
        ),
      ),
    );
  }

  Widget _card() {
    final c = ConnectionCenter.to;
    return Container(
      decoration: BoxDecoration(
        color: AppTheme.card,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: AppTheme.hairline),
        boxShadow: const [
          BoxShadow(
            color: Colors.black54,
            blurRadius: 14,
            offset: Offset(0, 5),
          ),
        ],
      ),
      child: Padding(
        padding: const EdgeInsets.fromLTRB(14, 12, 8, 12),
        child: switch (c.phase) {
          ConnPhase.scanning => _scanBody(c),
          ConnPhase.connecting => _lineBody(
            icon: Icons.bluetooth_searching,
            color: AppTheme.accent,
            spin: true,
            title: LocaleKeys.deviceConnecting.tr,
            detail: c.notice,
          ),
          ConnPhase.connected => _lineBody(
            icon: Icons.check_circle_outline,
            color: AppTheme.iconKeep,
            title: LocaleKeys.deviceConnected.tr,
            detail: c.notice,
          ),
          ConnPhase.failed => _failBody(c),
          ConnPhase.idle => const SizedBox.shrink(),
        },
      ),
    );
  }

  /// 扫描中：列设备给用户挑。
  Widget _scanBody(ConnectionCenter c) {
    final list = c.devices;
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _header(
          title: LocaleKeys.connPickTitle.tr,
          spinning: true,
          onClose: c.dismiss,
        ),
        const SizedBox(height: 6),
        if (list.isEmpty)
          Padding(
            padding: const EdgeInsets.only(right: 6, top: 6, bottom: 6),
            child: Text(
              LocaleKeys.connScanEmpty.tr,
              style: const TextStyle(
                color: AppTheme.muted,
                fontSize: 13,
                height: 1.4,
              ),
            ),
          )
        else
          for (final r in list.take(4))
            _deviceRow(c, r),
        const SizedBox(height: 10),
        Row(
          children: [
            TextButton(
              onPressed: c.open,
              child: Text(LocaleKeys.bleScanRescan.tr),
            ),
            const Spacer(),
            TextButton(
              onPressed: c.dismiss,
              child: Text(LocaleKeys.bleScanStop.tr),
            ),
          ],
        ),
      ],
    );
  }

  /// 一行状态（连接中 / 已连接）。
  Widget _lineBody({
    required IconData icon,
    required Color color,
    required String title,
    required String detail,
    bool spin = false,
  }) {
    return Row(
      children: [
        SizedBox.square(
          dimension: 20,
          child: spin
              ? CircularProgressIndicator(
                  strokeWidth: 2,
                  valueColor: AlwaysStoppedAnimation<Color>(color),
                )
              : Icon(icon, size: 20, color: color),
        ),
        const SizedBox(width: 12),
        Expanded(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                title,
                style: const TextStyle(
                  color: Colors.white,
                  fontSize: 14,
                  fontWeight: FontWeight.w700,
                  height: 1.2,
                ),
              ),
              if (detail.isNotEmpty)
                Text(
                  detail,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(color: AppTheme.muted, fontSize: 12),
                ),
            ],
          ),
        ),
      ],
    );
  }

  /// 失败：说清原因，并留在屏幕上等处理。
  Widget _failBody(ConnectionCenter c) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _header(
          title: LocaleKeys.bleScanConnectFailed.tr,
          icon: Icons.error_outline,
          color: AppTheme.iconOta,
          onClose: c.dismiss,
        ),
        if (c.notice.isNotEmpty)
          Padding(
            padding: const EdgeInsets.only(right: 6, top: 6),
            child: Text(
              c.notice,
              style: const TextStyle(
                color: AppTheme.muted,
                fontSize: 13,
                height: 1.4,
              ),
            ),
          ),
        const SizedBox(height: 6),
        Row(
          children: [
            TextButton(
              onPressed: c.retry,
              child: Text(LocaleKeys.connRetry.tr),
            ),
            const Spacer(),
            TextButton(
              onPressed: c.open,
              child: Text(LocaleKeys.bleScanRescan.tr),
            ),
          ],
        ),
      ],
    );
  }

  Widget _header({
    required String title,
    required VoidCallback onClose,
    IconData? icon,
    Color? color,
    bool spinning = false,
  }) {
    return Row(
      children: [
        if (spinning)
          const SizedBox.square(
            dimension: 16,
            child: CircularProgressIndicator(strokeWidth: 2),
          )
        else if (icon != null)
          Icon(icon, size: 18, color: color ?? AppTheme.muted),
        if (spinning || icon != null) const SizedBox(width: 10),
        Expanded(
          child: Text(
            title,
            style: const TextStyle(
              color: Colors.white,
              fontSize: 14,
              fontWeight: FontWeight.w700,
            ),
          ),
        ),
        IconButton(
          onPressed: onClose,
          iconSize: 18,
          visualDensity: VisualDensity.compact,
          color: AppTheme.muted,
          icon: const Icon(Icons.close),
        ),
      ],
    );
  }

  Widget _deviceRow(ConnectionCenter c, ScanResult r) {
    return InkWell(
      onTap: () => c.connectTo(r),
      borderRadius: BorderRadius.circular(10),
      child: Padding(
        padding: const EdgeInsets.fromLTRB(2, 9, 8, 9),
        child: Row(
          children: [
            Expanded(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    ConnectionCenter.nameOf(r.device),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 14,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                  Text(
                    '${r.device.remoteId.str}  ·  ${r.rssi} dBm',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                      color: AppTheme.muted,
                      fontSize: 11,
                    ),
                  ),
                ],
              ),
            ),
            const Icon(Icons.chevron_right, size: 18, color: AppTheme.muted),
          ],
        ),
      ),
    );
  }
}
