{"content": "import 'dart:async';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter_blue_plus/flutter_blue_plus.dart';
import 'package:get/get.dart';
import 'package:sifli_companion/app/app_theme.dart';
import 'package:sifli_companion/ble/connection_center.dart';
import 'package:sifli_companion/i18n/locale_keys.dart';

/// 连接码表的悬浮面板：中上方一片毛玻璃。
///
/// 常态不显示。只要发生连接动作就淡入滑下来 —— 用户点的、或后台自动回连的都算；
/// 连上后停一下自己收回去，失败则**留着不走**（连接失败最忌讳自己消失）。
///
/// 挂在 `GetMaterialApp.builder` 里，位置在所有路由**之外**，所以切页 / 返回都带不走
/// 它。「自动回连什么都没显示」正是靠这一层解决的。
///
/// 这一层没有 `Overlay`、没有 `Material` 祖先，也没有约束链，所以：
/// 不能用 `tooltip:`；点击反馈要自己包一层透明 `Material`（`InkWell` 找不到
/// `Material` 就没有水波纹）；宽度必须由 [Positioned] 钉死。
class ConnectionOverlay extends StatefulWidget {
  /// 创建连接面板。
  const ConnectionOverlay({super.key});

  @override
  State<ConnectionOverlay> createState() => _ConnectionOverlayState();
}

class _ConnectionOverlayState extends State<ConnectionOverlay>
    with SingleTickerProviderStateMixin {
  /// 0 = 收在屏幕上方之外，1 = 停到位。
  late final AnimationController _slide;

  bool _visible = false;

  /// 面板最大宽度；窄屏按比例再收。
  static const _panelMax = 360.0;

  /// 毛玻璃模糊半径。
  static const _blur = 22.0;

  /// 圆角。
  static const _radius = 20.0;

  StreamSubscription<void>? _sub;

  // 排版只用这几档，别在控件里散落字号。
  static const _title = TextStyle(
    fontSize: 14.5,
    height: 1.25,
    fontWeight: FontWeight.w600,
    letterSpacing: 0.2,
    color: Color(0xF2FFFFFF),
  );
  static const _name = TextStyle(
    fontSize: 14.5,
    height: 1.3,
    fontWeight: FontWeight.w600,
    color: Colors.white,
  );
  static const _meta = TextStyle(
    fontSize: 11.5,
    height: 1.35,
    letterSpacing: 0.3,
    color: AppTheme.muted,
    fontFeatures: [ui.FontFeature.tabularFigures()],
  );
  static const _hint = TextStyle(
    fontSize: 12.5,
    height: 1.5,
    color: AppTheme.muted,
  );

  @override
  void initState() {
    super.initState();
    _slide = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 300),
    );
    final center = ConnectionCenter.to;
    _visible = center.visible;
    if (_visible) _slide.value = 1;
    _sub = center.changes.listen((_) => _sync());
  }

  @override
  void dispose() {
    _sub?.cancel();
    _slide.dispose();
    super.dispose();
  }

  void _sync() {
    if (!mounted) return;
    final has = ConnectionCenter.to.visible;
    if (has != _visible) {
      _visible = has;
      if (has) {
        _slide.forward();
      } else {
        _slide.reverse();
      }
    }
    setState(() {});
  }

  @override
  Widget build(BuildContext context) {
    final mq = MediaQuery.of(context);
    // 中上方：压在状态栏下面一点。
    final top = mq.padding.top + 10;
    final w = _panelMax.clamp(0.0, mq.size.width - 36);

    return Positioned(
      top: top,
      left: 18,
      right: 18,
      child: Center(
        child: SizedBox(
          width: w,
          child: AnimatedBuilder(
            animation: _slide,
            builder: (context, child) {
              final t = Curves.easeOutCubic.transform(_slide.value);
              return FractionalTranslation(
                // 从上方滑下来。
                translation: Offset(0, t - 1),
                child: Opacity(
                  opacity: t,
                  child: IgnorePointer(ignoring: !_visible, child: child),
                ),
              );
            },
            child: _glass(),
          ),
        ),
      ),
    );
  }

  /// 毛玻璃外壳：模糊 + 半透明底 + 顶部高光 + 一道细描边。
  Widget _glass() {
    return ClipRRect(
      borderRadius: BorderRadius.circular(_radius),
      child: BackdropFilter(
        filter: ui.ImageFilter.blur(sigmaX: _blur, sigmaY: _blur),
        child: DecoratedBox(
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(_radius),
            border: Border.all(color: Colors.white.withValues(alpha: 0.10)),
            gradient: LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              colors: [
                const Color(0xFF26262B).withValues(alpha: 0.72),
                const Color(0xFF101013).withValues(alpha: 0.66),
              ],
            ),
          ),
          child: Padding(
            padding: const EdgeInsets.fromLTRB(18, 14, 10, 8),
            child: _body(),
          ),
        ),
      ),
    );
  }

  Widget _body() {
    final c = ConnectionCenter.to;
    return switch (c.phase) {
      ConnPhase.scanning => _scanBody(c),
      ConnPhase.connecting => _statusBody(
        spin: true,
        title: LocaleKeys.deviceConnecting.tr,
        detail: c.notice,
      ),
      ConnPhase.connected => _statusBody(
        icon: Icons.check_circle_outline,
        color: AppTheme.iconKeep,
        title: LocaleKeys.deviceConnected.tr,
        detail: c.notice,
      ),
      ConnPhase.failed => _failBody(c),
      ConnPhase.idle => const SizedBox.shrink(),
    };
  }

  Widget _scanBody(ConnectionCenter c) {
    final list = c.devices;
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _header(
          icon: Icons.bluetooth_searching,
          color: AppTheme.accent,
          title: LocaleKeys.connPickTitle.tr,
          onClose: c.dismiss,
        ),
        if (list.isEmpty)
          Padding(
            padding: const EdgeInsets.fromLTRB(0, 10, 8, 4),
            child: Text(LocaleKeys.connScanEmpty.tr, style: _hint),
          )
        else
          Padding(
            padding: const EdgeInsets.only(top: 6),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [for (final r in list.take(4)) _deviceRow(c, r)],
            ),
          ),
        const SizedBox(height: 6),
        _actions(
          onLeft: (text: LocaleKeys.bleScanRescan.tr, tap: c.open),
          onRight: (text: LocaleKeys.bleScanStop.tr, tap: c.dismiss),
        ),
      ],
    );
  }

  Widget _statusBody({
    required String title,
    required String detail,
    IconData? icon,
    Color? color,
    bool spin = false,
  }) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Row(
          children: [
            if (spin)
              const SizedBox.square(
                dimension: 15,
                child: CircularProgressIndicator(
                  strokeWidth: 1.8,
                  valueColor: AlwaysStoppedAnimation<Color>(AppTheme.accent),
                ),
              )
            else
              Icon(icon, size: 17, color: color ?? AppTheme.muted),
            const SizedBox(width: 10),
            Expanded(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(title, style: _title),
                  if (detail.isNotEmpty) ...[
                    const SizedBox(height: 1),
                    Text(
                      detail,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: _meta,
                    ),
                  ],
                ],
              ),
            ),
            const SizedBox(width: 8),
          ],
        ),
        const SizedBox(height: 12),
      ],
    );
  }

  Widget _failBody(ConnectionCenter c) {
    return Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _header(
          icon: Icons.error_outline,
          color: AppTheme.iconOta,
          title: LocaleKeys.bleScanConnectFailed.tr,
          onClose: c.dismiss,
        ),
        if (c.notice.isNotEmpty)
          Padding(
            padding: const EdgeInsets.fromLTRB(0, 8, 8, 4),
            child: Text(c.notice, style: _hint),
          ),
        const SizedBox(height: 6),
        _actions(
          onLeft: (text: LocaleKeys.connRetry.tr, tap: c.retry),
          onRight: (text: LocaleKeys.bleScanRescan.tr, tap: c.open),
        ),
      ],
    );
  }

  Widget _header({
    required String title,
    required IconData icon,
    required Color color,
    required VoidCallback onClose,
  }) {
    return Row(
      children: [
        Icon(icon, size: 17, color: color),
        const SizedBox(width: 10),
        Expanded(child: Text(title, style: _title)),
        _iconTap(
          Icons.close,
          onClose,
          size: 16,
          color: AppTheme.muted,
        ),
      ],
    );
  }

  /// 轻量图标按钮：自己带一层透明 Material，水波纹才有地方落。
  Widget _iconTap(
    IconData icon,
    VoidCallback tap, {
    required double size,
    required Color color,
  }) {
    return Material(
      type: MaterialType.transparency,
      child: InkResponse(
        onTap: tap,
        radius: 18,
        child: Padding(
          padding: const EdgeInsets.all(6),
          child: Icon(icon, size: size, color: color),
        ),
      ),
    );
  }

  /// 底部一行操作：左边主操作，右边次操作，都做成轻量的文字按钮。
  Widget _actions({
    required ({String text, VoidCallback tap}) onLeft,
    required ({String text, VoidCallback tap}) onRight,
  }) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.end,
      children: [
        _action(onLeft.text, onLeft.tap, primary: true),
        const SizedBox(width: 4),
        _action(onRight.text, onRight.tap),
      ],
    );
  }

  Widget _action(String text, VoidCallback tap, {bool primary = false}) {
    return Material(
      type: MaterialType.transparency,
      child: InkWell(
        onTap: tap,
        borderRadius: BorderRadius.circular(10),
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 9),
          child: Text(
            text,
            style: TextStyle(
              fontSize: 13,
              fontWeight: FontWeight.w600,
              letterSpacing: 0.2,
              color: primary ? AppTheme.accent : AppTheme.muted,
            ),
          ),
        ),
      ),
    );
  }

  Widget _deviceRow(ConnectionCenter c, ScanResult r) {
    return Material(
      type: MaterialType.transparency,
      child: InkWell(
        onTap: () => c.connectTo(r),
        borderRadius: BorderRadius.circular(12),
        child: Padding(
          padding: const EdgeInsets.fromLTRB(0, 10, 6, 10),
          child: Row(
            children: [
              Expanded(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      ConnectionCenter.nameOf(r.device),
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: _name,
                    ),
                    const SizedBox(height: 2),
                    Text(
                      '${r.device.remoteId.str}   ${r.rssi} dBm',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: _meta,
                    ),
                  ],
                ),
              ),
              const Icon(
                Icons.chevron_right,
                size: 18,
                color: Color(0x59FFFFFF),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
