/// 连接状态的图形：状态靠它说，不靠文字。
///
/// - 扫描：三圈向外扩散的雷达环；
/// - 连接：一段绕圈的弧；
/// - 成功：绿环外扩一次 + 勾按笔画描出来；
/// - 失败：红环收进来 + 感叹号弹出来。
///
/// 扫描/连接是循环动画，成功/失败只播一次（停住就是最终态，不需要额外的静态图）。
class _StateGlyph extends StatefulWidget {
  const _StateGlyph({required this.phase});

  final ConnPhase phase;

  @override
  State<_StateGlyph> createState() => _StateGlyphState();
}

class _StateGlyphState extends State<_StateGlyph>
    with SingleTickerProviderStateMixin {
  late final AnimationController _c;

  @override
  void initState() {
    super.initState();
    _c = AnimationController(vsync: this);
    _sync();
  }

  @override
  void didUpdateWidget(_StateGlyph old) {
    super.didUpdateWidget(old);
    if (old.phase != widget.phase) _sync();
  }

  @override
  void dispose() {
    _c.dispose();
    super.dispose();
  }

  void _sync() {
    _c.stop();
    switch (widget.phase) {
      case ConnPhase.scanning:
        _c.duration = const Duration(milliseconds: 1700);
        _c.repeat();
      case ConnPhase.connecting:
        _c.duration = const Duration(milliseconds: 1100);
        _c.repeat();
      case ConnPhase.connected:
        _c.duration = const Duration(milliseconds: 520);
        _c.forward(from: 0);
      case ConnPhase.failed:
        _c.duration = const Duration(milliseconds: 620);
        _c.forward(from: 0);
      case ConnPhase.idle:
        break;
    }
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _c,
      builder: (context, _) => CustomPaint(
        painter: _GlyphPainter(phase: widget.phase, t: _c.value),
        child: const SizedBox.expand(),
      ),
    );
  }
}

class _GlyphPainter extends CustomPainter {
  _GlyphPainter({required this.phase, required this.t});

  final ConnPhase phase;
  final double t;

  static const _ink = Color(0xF2FFFFFF);
  static const _ok = AppTheme.iconKeep;
  static const _fail = AppTheme.danger;

  @override
  void paint(Canvas canvas, Size size) {
    final c = size.center(Offset.zero);
    final r0 = size.width * 0.10;
    final edge = size.width / 2;

    switch (phase) {
      case ConnPhase.scanning:
        for (var k = 0; k < 3; k++) {
          final p = (t + k / 3) % 1.0;
          canvas.drawCircle(
            c,
            r0 + (edge - r0) * p,
            Paint()
              ..style = PaintingStyle.stroke
              ..strokeWidth = 1.4
              ..color = _ink.withValues(alpha: 0.42 * (1 - p)),
          );
        }
        canvas.drawCircle(c, r0 * 1.5, Paint()..color = _ink.withValues(alpha: 0.85));

      case ConnPhase.connecting:
        final r = size.width * 0.33;
        canvas.drawCircle(
          c,
          r,
          Paint()
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1
            ..color = _ink.withValues(alpha: 0.16),
        );
        canvas.drawArc(
          Rect.fromCircle(center: c, radius: r),
          t * 2 * math.pi,
          1.9,
          false,
          Paint()
            ..style = PaintingStyle.stroke
            ..strokeWidth = 2.2
            ..strokeCap = StrokeCap.round
            ..color = _ink.withValues(alpha: 0.92),
        );
        canvas.drawCircle(c, r0 * 1.5, Paint()..color = _ink.withValues(alpha: 0.85));

      case ConnPhase.connected:
        canvas.drawCircle(
          c,
          r0 + (edge - r0) * t,
          Paint()
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1.6
            ..color = _ok.withValues(alpha: 0.45 * (1 - t)),
        );
        final path = Path()
          ..moveTo(c.dx - size.width * 0.20, c.dy + size.width * 0.01)
          ..lineTo(c.dx - size.width * 0.06, c.dy + size.width * 0.15)
          ..lineTo(c.dx + size.width * 0.21, c.dy - size.width * 0.16);
        final metric = path.computeMetrics().first;
        // 环先扩，勾后画，两段不重叠。
        final p = ((t - 0.35) / 0.65).clamp(0.0, 1.0);
        if (p > 0) {
          canvas.drawPath(
            metric.extractPath(0, metric.length * p),
            Paint()
              ..style = PaintingStyle.stroke
              ..strokeWidth = 2.6
              ..strokeCap = StrokeCap.round
              ..strokeJoin = StrokeJoin.round
              ..color = _ok,
          );
        }

      case ConnPhase.failed:
        canvas.drawCircle(
          c,
          edge - (edge - r0) * t,
          Paint()
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1.6
            ..color = _fail.withValues(alpha: 0.40 * (1 - t)),
        );
        final a = ((t - 0.15) / 0.85).clamp(0.0, 1.0);
        if (a > 0) {
          final top = c.dy - size.width * 0.20;
          final end = c.dy + size.width * 0.04;
          canvas.drawLine(
            Offset(c.dx, top),
            Offset(c.dx, top + (end - top) * a),
            Paint()
              ..strokeWidth = 2.6
              ..strokeCap = StrokeCap.round
              ..color = _fail,
          );
          if (a > 0.7) {
            canvas.drawCircle(
              Offset(c.dx, c.dy + size.width * 0.15),
              1.9,
              Paint()..color = _fail,
            );
          }
        }

      case ConnPhase.idle:
        break;
    }
  }

  @override
  bool shouldRepaint(covariant _GlyphPainter old) =>
      old.t != t || old.phase != phase;
}
