  Future<void> startPairing() async {
    found.clear();
    linkError.value = null;
    if (!await BleManager().requestPermissions()) {
      AppTheme.snack(
        LocaleKeys.bleSnackbarTitle.tr,
        LocaleKeys.bleScanPermissionDenied.tr,
      );
      return;
    }
    if (FlutterBluePlus.adapterStateNow != BluetoothAdapterState.on) {
      await BleManager().turnOn();
      await Future<void>.delayed(const Duration(milliseconds: 500));
      if (FlutterBluePlus.adapterStateNow != BluetoothAdapterState.on) {
        AppTheme.snack(
          LocaleKeys.bleSnackbarTitle.tr,
          LocaleKeys.bleScanTurnOnBluetooth.tr,
        );
        return;
      }
    }

    pairing.value = true;
    await _scanSub?.cancel();
    _scanSub = FlutterBluePlus.scanResults.listen((results) {
      var dirty = false;
      for (final r in results) {
        if (!r.advertisementData.connectable) continue;
        // 这里就是「配对」这个用途，只列码表，不该混进耳机音箱。
        if (!CompanionProto.matchesAdvName(nameOf(r.device))) continue;
        final id = r.device.remoteId.str;
        final i = found.indexWhere((e) => e.device.remoteId.str == id);
        if (i >= 0) {
          found[i] = r;
        } else {
          found.add(r);
          dirty = true;
        }
      }
      if (dirty) found.sort((a, b) => b.rssi.compareTo(a.rssi));
    });
    await BleManager().startScan(withKeywords: CompanionProto.scanKeywords);
  }

  /// 关掉配对区（用户取消）。
  void stopPairing() {
    _scanSub?.cancel();
    _scanSub = null;
    unawaited(BleManager().stopScan());
    pairing.value = false;
    found.clear();
  }

  /// 连一台扫到的码表。
  Future<void> connectTo(BluetoothDevice device) async {
    if (_busy) return;
    _busy = true;
    _scanSub?.cancel();
    _scanSub = null;
    unawaited(BleManager().stopScan());
    linkError.value = null;
    try {
      await client.connect(device);
      if (client.state == CompanionConnState.ready) {
        await onConnected();
        pairing.value = false;
        found.clear();
        AppTheme.snack(
          LocaleKeys.bleSnackbarTitle.tr,
          LocaleKeys.bleScanConnected.trParams({'name': nameOf(device)}),
        );
      } else if (client.state == CompanionConnState.versionMismatch) {
        linkError.value = LocaleKeys.deviceMismatch.tr;
      } else {
        linkError.value = LocaleKeys.bleScanConnectFailed.tr;
      }
    } catch (e, st) {
      await AppLog.e('Shell', '连接失败: $e', st);
      linkError.value = LocaleKeys.bleScanConnectFailed.tr;
    } finally {
      _busy = false;
    }
  }

  /// 重试上一次的设备；没有记录就回到扫描。
  Future<void> retryConnect() async {
    final d = client.device;
    if (d == null) {
      await startPairing();
      return;
    }
    await connectTo(d);
  }""")
