      h < 0 || h > 23 || mi < 0 || mi > 59 || s < 0 || s > 60) {
    return 0;
  }

  for (i = 1970; i < y; i++) {
    days += 365 + gnss_is_leap(i);
  }

  for (i = 0; i < mo - 1; i++) {
    days += md[i];
    if (i == 1 && gnss_is_leap(y)) {
      days++;
    }
  }

  days += d - 1;
  return (time_t)(days * 86400L + h * 3600L + mi * 60L + s);
}

