/// 星历同步的"下次同步"状态。星历页和设备页都要显示同一份，所以放在这里统一算：
/// 只有一处知道"什么时候该同步"（[EphAutoSync.maxAge]），界面不该各算各的。
class EphSyncStatus {
  /// 创建状态。
  const EphSyncStatus({
    this.newest,
    this.listed = false,
    this.connected = false,
  });

  /// 还没查过（没连上码表 / 目录列不出来）。
  const EphSyncStatus.unknown()
      : newest = null,
        listed = false,
        connected = false;

  /// 码表上最新一份星历的时间（本地时区）。[listed] 为真时它才有意义。
  final DateTime? newest;

  /// 是否成功列过码表目录。
  final bool listed;

  /// 刷新这一刻码表是否在线。
  final bool connected;

  /// 下次自动同步的时间点；没有星历时为 null（= 连上就同步）。
  DateTime? get nextAt => newest?.add(EphAutoSync.maxAge);

  /// 是否已经到期（没有星历，或过了 [nextAt]）。
  bool get due {
    final at = nextAt;
    if (at == null) return true;
    return DateTime.now().isAfter(at);
  }

  /// 给界面用的一句话（星历页和设备页共用，避免两处文案漂移）。
  String get label {
    if (!connected) return LocaleKeys.ephNextOnConnect.tr;
    if (nextAt == null) return LocaleKeys.ephNextNone.tr;
    if (due) return LocaleKeys.ephNextDue.tr;
    return LocaleKeys.ephNextAt.trParams({'time': _stamp(nextAt!)});
  }

  /// `今天 18:20` / `明天 09:12` / `2026/9/18 09:12`。
  static String _stamp(DateTime t) {
    final l = t.toLocal();
    final now = DateTime.now();
    final hh = l.hour.toString().padLeft(2, '0');
    final mm = l.minute.toString().padLeft(2, '0');
    final hm = '$hh:$mm';
    final d0 = DateTime(now.year, now.month, now.day);
    final d1 = DateTime(l.year, l.month, l.day);
    final days = d1.difference(d0).inDays;
    if (days == 0) return '${LocaleKeys.ephToday.tr} $hm';
    if (days == 1) return '${LocaleKeys.ephTomorrow.tr} $hm';
    return '${l.year}/${l.month}/${l.day} $hm';
  }
}
