assert 'class EphSyncStatus' not in s
s += """
/// 「下次同步」状态：星历页和设备页共用一份，避免两处各算各的、文案漂移。
class EphSyncStatus {
  /// 创建状态。
  const EphSyncStatus({
    this.newest,
    this.listed = false,
    this.connected = false,
  });

  /// 还没查过（没连上码表 / 目录列不出来）。
  const EphSyncStatus.unknown()
      : newest = null,
        listed = false,
        connected = false;

  /// 码表上最新一份星历的时间（本地时区）。[listed] 为真时它才有意义。
  final DateTime? newest;

  /// 是否成功列过码表目录（false = 本次结果不可信，按「没查过」显示）。
  final bool listed;

  /// 刷新这一刻码表是否在线。
  final bool connected;

  /// 下次自动同步的时间点：最新星历时间 + [EphAutoSync.maxAge]。
  ///
  /// 没有星历时为 null —— 那是「一连上就同步」。
  DateTime? get nextAt => newest?.add(EphAutoSync.maxAge);

  /// 是否已经到期（没有星历，或已过 [nextAt]）。
  bool get due {
    final at = nextAt;
    return at == null || DateTime.now().isAfter(at);
  }

  /// 给界面显示的一句话。
  String get label {
    if (!connected) return LocaleKeys.ephNextOnConnect.tr;
    final at = nextAt;
    if (at == null) return LocaleKeys.ephNextNone.tr;
    if (due) return LocaleKeys.ephNextDue.tr;
    return LocaleKeys.ephNextAt.trParams({'time': _stamp(at)});
  }

  /// `今天 18:20` / `明天 09:12` / `2026/9/18 09:12`。
  static String _stamp(DateTime t) {
    final l = t.toLocal();
    final now = DateTime.now();
    final hm = '${l.hour.toString().padLeft(2, '0')}:'
        '${l.minute.toString().padLeft(2, '0')}';
    final today = DateTime(now.year, now.month, now.day);
    final day = DateTime(l.year, l.month, l.day);
    final days = day.difference(today).inDays;
    if (days == 0) return '${LocaleKeys.ephToday.tr} $hm';
    if (days == 1) return '${LocaleKeys.ephTomorrow.tr} $hm';
    return '${l.year}/${l.month}/${l.day} $hm';
  }
}
"""
io.open('lib/gnss/eph_auto_sync.dart','w',encoding='utf-8').write(s)
