/// 一个统计区间：本地时间的「日」边界，含头不含尾。
class RideRange {
  const RideRange(this.start, this.end);

  final DateTime start;
  final DateTime end;

  /// 区间是否包含今天（= 当前这一周 / 这一月）。
  bool get isCurrent {
    final now = DateTime.now();
    return !now.isBefore(start) && now.isBefore(end);
  }

  /// 区间内的天数（周 7、月 28–31）。
  int get days => end.difference(start).inDays;

  bool contains(DateTime t) => !t.isBefore(start) && t.isBefore(end);

  bool containsUnix(int unixSec) =>
      unixSec > 0 && contains(DateTime.fromMillisecondsSinceEpoch(unixSec * 1000));
}

/// 区间里一格的合计（周/月都按天分格）。
class RideBucket {
  const RideBucket({this.rides = 0, this.km = 0, this.durationSec = 0});

  final int rides;
  final double km;
  final int durationSec;

  bool get isEmpty => rides == 0;
}

/// 把骑行记录按周 / 月切成柱子用的格子，并算区间合计。
abstract class RidePeriodStats {
  /// 周一为一周的第一天（和 `RidePeriodFilter.weekStart` 一致）。
  static DateTime weekStart(DateTime d) {
    final day = DateTime(d.year, d.month, d.day);
    return day.subtract(Duration(days: day.weekday - 1));
  }

  static DateTime monthStart(DateTime d) => DateTime(d.year, d.month, 1);

  /// 锚点所在的区间；[RidePeriod.all] 没有区间（返回 null）。
  static RideRange? range(RidePeriod period, DateTime anchor) {
    switch (period) {
      case RidePeriod.week:
        final s = weekStart(anchor);
        return RideRange(s, s.add(const Duration(days: 7)));
      case RidePeriod.month:
        final s = monthStart(anchor);
        final e = s.month == 12 ? DateTime(s.year + 1, 1, 1) : DateTime(s.year, s.month + 1, 1);
        return RideRange(s, e);
      case RidePeriod.all:
        return null;
    }
  }

  /// 往前 / 往后挪一个周期。[RidePeriod.all] 不动。
  static DateTime shift(RidePeriod period, DateTime anchor, int delta) {
    switch (period) {
      case RidePeriod.week:
        return anchor.add(Duration(days: 7 * delta));
      case RidePeriod.month:
        // 用「月首」挪，避免 1/31 往前一个月落到 12/31 这类越界。
        final s = monthStart(anchor);
        return DateTime(s.year, s.month + delta, 1);
      case RidePeriod.all:
        return anchor;
    }
  }

  /// 还能不能往后挪：下一个区间的起点不能越过今天（不允许看未来）。
  static bool canForward(RidePeriod period, DateTime anchor) {
    final next = shift(period, anchor, 1);
    final r = range(period, next);
    if (r == null) return false;
    final today = DateTime.now();
    return r.start.isBefore(DateTime(today.year, today.month, today.day).add(const Duration(days: 1)))
        && !r.start.isAfter(today);
  }
