import 'package:get/get.dart';
import 'package:sifli_companion/app/app_routes.dart';
import 'package:sifli_companion/app/app_theme.dart';
import 'package:sifli_companion/i18n/locale_keys.dart';
import 'package:sifli_companion/ride/ride_period_stats.dart';
import 'package:sifli_companion/ride/ride_record_store.dart';
import 'package:sifli_companion/ride/ride_week_goals.dart';
import 'package:sifli_companion/ui/ride/ride_charts.dart';
import 'package:sifli_companion/ui/ride/ride_period_header.dart';
import 'package:sifli_companion/ui/ride/ride_track_thumb.dart';
import 'package:sifli_companion/ui/shell/shell_controller.dart';
import 'package:sifli_companion/ui/widgets/helm_chrome.dart';

/// 数据统计（二级页）：按周 / 月翻看逐日柱状图，以及那个区间的骑行记录。
///
/// 主页面只留「当前周 / 当前月」，翻历史在这里做 —— 主界面不被图表塞满，
/// 图表也有足够宽度画清楚（月有 28–31 根柱子）。
class RideStatsPage extends StatefulWidget {
  /// 创建统计页。
  const RideStatsPage({super.key});

  @override
  State<RideStatsPage> createState() => _RideStatsPageState();
}

class _RideStatsPageState extends State<RideStatsPage> {
  RidePeriod _period = RidePeriod.week;
  DateTime _anchor = DateTime.now();
  bool _hydrating = false;

  @override
  void initState() {
    super.initState();
    _maybeHydrate();
  }

  /// 时长要先算过才有（和主页一样）：索引里缺就补一次，补完刷新图表。
  void _maybeHydrate() {
    if (_hydrating) return;
    final all = RideRecordStore().items;
    if (all.every((r) => r.durationSec != null && r.preview != null)) return;
    _hydrating = true;
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      final changed = await RideRecordStore().ensureDurations();
      _hydrating = false;
      if (changed && mounted) setState(() {});
    });
  }

  /// 区间名：当前的写「本周 / 本月」，历史的写具体范围（跨年才带年份）。
  String _rangeLabel(RideRange range) {
    final now = DateTime.now();
    if (range.isCurrent) {
      return _period == RidePeriod.week
          ? LocaleKeys.rideThisWeek.tr
          : LocaleKeys.rideThisMonth.tr;
    }
    if (_period == RidePeriod.week) {
      final a = range.start;
      final b = range.end.subtract(const Duration(days: 1));
      final left =
          a.year == now.year ? '${a.month}/${a.day}' : '${a.year}/${a.month}/${a.day}';
      final right =
          b.year == now.year ? '${b.month}/${b.day}' : '${b.year}/${b.month}/${b.day}';
      return '$left – $right';
    }
    return '${range.start.year}/${range.start.month}';
  }

  /// 往前 / 往后挪一个周期（-1 = 更早）。不允许走进未来。
  void _stepPeriod(RideRange range, int delta) {
    final next = RidePeriodStats.shift(_period, _anchor, delta);
    final r = RidePeriodStats.range(_period, next);
    if (r == null) return;
    final now = DateTime.now();
    if (delta > 0 && r.start.isAfter(DateTime(now.year, now.month, now.day))) {
      return;
    }
    setState(() {
      _anchor = next;
      _period = _period;
    });
  }

  void _backToNow() => setState(() => _anchor = DateTime.now());

  @override
  Widget build(BuildContext context) {
    final shell = Get.isRegistered<ShellController>()
        ? Get.find<ShellController>()
        : null;

    return Scaffold(
      appBar: AppBar(title: Text(LocaleKeys.rideStatsTitle.tr)),
      body: Obx(() {
        // 码表同步完成后主页会 bump，这里跟着刷新。
        shell?.rideTick.value;
        final all = RideRecordStore().items;
        _maybeHydrate();

        final range = RidePeriodStats.range(_period, _anchor)!;
        final label = _rangeLabel(range);
        final buckets = RidePeriodStats.buckets(all, range);
        final total = RidePeriodStats.total(buckets);
        final rides = RidePeriodStats.inRange(all, range);

        return ListView(
          padding: const EdgeInsets.fromLTRB(16, 8, 16, 28),
          children: [
            SegmentedButton<RidePeriod>(
              segments: [
                ButtonSegment(
                  value: RidePeriod.week,
                  label: Text(LocaleKeys.ridePeriodWeek.tr),
                ),
                ButtonSegment(
                  value: RidePeriod.month,
                  label: Text(LocaleKeys.ridePeriodMonth.tr),
                ),
              ],
              selected: {_period},
              showSelectedIcon: false,
              onSelectionChanged: (next) =>
                  setState(() => _period = next.first),
            ),
            const SizedBox(height: 12),
            RidePeriodHeader(
              label: label,
              canBack: _hasEarlier(all, range),
              canForward: RidePeriodStats.canForward(_period, _anchor),
              onStep: (d) => _stepPeriod(range, d),
              onNow: range.isCurrent ? null : _backToNow,
            ),
            const SizedBox(height: 10),
            _statsCard(range, buckets, total),
            const SizedBox(height: 18),
            HelmSectionTitle(LocaleKeys.rideRecentIn.trParams({'range': label})),
            if (rides.isEmpty)
              HelmCard(
                padding: const EdgeInsets.fromLTRB(20, 28, 20, 28),
                child: Text(
                  LocaleKeys.rideEmptyIn.trParams({'range': label}),
                  textAlign: TextAlign.center,
                  style: const TextStyle(color: AppTheme.muted, height: 1.45),
                ),
              )
            else
              HelmCard(
                child: HelmTileGroup(
                  children: [
                    for (final ride in rides)
                      HelmNavTile(
                        color: AppTheme.iconRide,
                        icon: Icons.pedal_bike,
                        leading: RideTrackThumb(
                          points: ride.preview ?? const [],
                        ),
                        title: ride.title,
                        subtitle: [
                          _fmtTime(ride.mtime),
                          if (ride.durationSec != null && ride.durationSec! > 0)
                            GpxUtil.formatElapsed(
                              Duration(seconds: ride.durationSec!),
                            ),
                          if (ride.distanceKm != null && ride.distanceKm! > 0)
                            LocaleKeys.rideDistance.trParams({
                              'km': ride.distanceKm!.toStringAsFixed(1),
                            }),
                        ].where((s) => s.isNotEmpty).join(' · '),
                        onTap: () => Get.toNamed(
                          AppRoutes.rideDetail,
                          arguments: ride.fileName,
                        ),
                      ),
                  ],
                ),
              ),
          ],
        );
      }),
    );
  }

  /// 区间之前还有没有记录：没有就把「往前」置灰，省得一路翻到空白。
  bool _hasEarlier(List<RideRecord> all, RideRange range) {
    for (final r in all) {
      if (r.mtime <= 0) continue;
      final t = DateTime.fromMillisecondsSinceEpoch(r.mtime * 1000);
      if (t.isBefore(range.start)) return true;
    }
    return false;
  }

  String _fmtTime(int unix) {
    if (unix <= 0) return '';
    final d = DateTime.fromMillisecondsSinceEpoch(unix * 1000);
    final y = d.year.toString().padLeft(4, '0');
    final m = d.month.toString().padLeft(2, '0');
    final day = d.day.toString().padLeft(2, '0');
    final h = d.hour.toString().padLeft(2, '0');
    final min = d.minute.toString().padLeft(2, '0');
    return '$y-$m-$day $h:$min';
  }

  /// 统计卡：合计三项 + 每日里程 / 每日时长两张柱状图。
  Widget _statsCard(
    RideRange range,
    List<RideBucket> buckets,
    RideBucket total,
  ) {
    final today = range.todayIndex();
    final km = [for (final b in buckets) b.km];
    final mins = [for (final b in buckets) b.durationSec / 60.0];
    final n = buckets.isEmpty ? 1 : buckets.length;
    final labels = _bucketLabels(range);
    final kmAvg = total.km / n;
    final minAvg = total.durationSec / 60.0 / n;

    return HelmCard(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(16, 14, 16, 10),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                _bigStat(
                  LocaleKeys.rideStatRides.tr,
                  '${total.rides}',
                  AppTheme.ringOrange,
                ),
                _bigStat(
                  LocaleKeys.rideStatTime.tr,
                  RideWeekGoals.formatSeconds(total.durationSec),
                  AppTheme.ringLime,
                ),
                _bigStat(
                  LocaleKeys.rideStatKm.tr,
                  total.km.toStringAsFixed(1),
                  AppTheme.ringCyan,
                ),
              ],
            ),
            const SizedBox(height: 14),
            _chartBlock(
              title: LocaleKeys.rideChartDistance.tr,
              totalText: LocaleKeys.rideChartTotal.trParams({
                'v': '${total.km.toStringAsFixed(1)} km',
              }),
              avgText: LocaleKeys.rideChartAvg.trParams({
                'v': '${kmAvg.toStringAsFixed(1)} km',
              }),
              values: km,
              avg: kmAvg,
              labels: labels,
              color: AppTheme.ringCyan,
              highlight: today,
            ),
            const SizedBox(height: 10),
            _chartBlock(
              title: LocaleKeys.rideChartTime.tr,
              totalText: LocaleKeys.rideChartTotal.trParams({
                'v': RideWeekGoals.formatSeconds(total.durationSec),
              }),
              avgText: LocaleKeys.rideChartAvg.trParams({
                'v': RideWeekGoals.formatMinutes(minAvg.round()),
              }),
              values: mins,
              avg: minAvg,
              labels: labels,
              color: AppTheme.ringLime,
              highlight: today,
            ),
          ],
        ),
      ),
    );
  }

  Widget _bigStat(String label, String value, Color color) {
    return Expanded(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                width: 8,
                height: 8,
                decoration: BoxDecoration(color: color, shape: BoxShape.circle),
              ),
              const SizedBox(width: 6),
              Text(
                label,
                style: const TextStyle(color: AppTheme.muted, fontSize: 12),
              ),
            ],
          ),
          const SizedBox(height: 4),
          Text(
            value,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
              color: Colors.white,
              fontSize: 19,
              fontWeight: FontWeight.w700,
            ),
          ),
        ],
      ),
    );
  }

  Widget _chartBlock({
    required String title,
    required String totalText,
    required String avgText,
    required List<double> values,
    required double avg,
    required List<String> labels,
    required Color color,
    required int highlight,
  }) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          children: [
            Text(
              title,
              style: const TextStyle(
                color: Colors.white,
                fontSize: 13,
                fontWeight: FontWeight.w600,
              ),
            ),
            const Spacer(),
            // 窄屏 / 大数字（合计 1,234.5 km）也别撑破一行。
            Flexible(
              child: Text(
                '$totalText · $avgText',
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                textAlign: TextAlign.right,
                style: const TextStyle(color: AppTheme.muted, fontSize: 12),
              ),
            ),
          ],
        ),
        const SizedBox(height: 2),
        RideBarChart(
          values: values,
          labels: labels,
          color: color,
          avg: avg,
          highlight: highlight,
        ),
      ],
    );
  }

  /// 柱子下方标签：周用星期几（一…日）；月只标 1/5/10…，免得 31 个数字挤成一团。
  List<String> _bucketLabels(RideRange range) {
    if (_period == RidePeriod.week) {
      const keys = [
        LocaleKeys.rideWd1,
        LocaleKeys.rideWd2,
        LocaleKeys.rideWd3,
        LocaleKeys.rideWd4,
        LocaleKeys.rideWd5,
        LocaleKeys.rideWd6,
        LocaleKeys.rideWd7,
      ];
      return [for (var i = 0; i < range.days; i++) keys[i % 7].tr];
    }
    return [
      for (var i = 0; i < range.days; i++)
        () {
          final day = range.start.add(Duration(days: i)).day;
          return (day == 1 || day % 5 == 0) ? '$day' : '';
        }(),
    ];
  }
