class HelmReveal extends StatefulWidget {
  const HelmReveal({
    super.key,
    required this.child,
    this.delay = Duration.zero,
    this.offset = 0.035,
    this.duration = const Duration(milliseconds: 320),
  });

  final Widget child;
  final Duration delay;
  final double offset;
  final Duration duration;

  /// 按序号算延迟：第 0 个不延迟，之后每 [step] 一个，最多到 [maxDelay]。
  static Duration stagger(int index, {Duration step = const Duration(milliseconds: 45), Duration maxDelay = const Duration(milliseconds: 270)}) {
    final d = step * index;
    return d > maxDelay ? maxDelay : d;
  }

