List<LatLng>? _previewFromJson(Object? raw) {
  if (raw is! List) return null;
  final out = <LatLng>[];
  for (final e in raw) {
    if (e is List && e.length >= 2) {
      final lat = (e[0] as num?)?.toDouble();
      final lon = (e[1] as num?)?.toDouble();
      if (lat != null && lon != null) out.add(LatLng(lat, lon));
    }
  }
  return out;
}
